fontpath='C:/Windows/Fonts/arial.ttf'
boldpath='C:/Windows/Fonts/arialbd.ttf'
def wrap(text,font,width,d):
 lines=[]
 for part in text.split('\n'):
  line=''
  for word in part.split(' '):
   test=(line+' '+word).strip()
   if d.textlength(test,font=font)>width and line: lines.append(line);line=word
   else: line=test
  lines.append(line)
 return '\n'.join(lines)
for index,page in enumerate(pages):
 im=Image.new('RGB',(page['width'],page['height']),'white');d=ImageDraw.Draw(im)
 for n in page['nodes']:
  x,y,w,h=n['x'],n['y'],n['w'],n['h'];kind=n['kind']
  if kind=='process': d.rounded_rectangle((x,y,x+w,y+h),radius=16,fill='#f0fdf4',outline='#4b7057',width=2)
  elif kind=='actor':
   d.rectangle((x,y,x+w,y+h),outline='#334155',width=2)
   d.line((x,y+20,x+20,y),fill='#334155',width=2)
  elif kind=='store':
   d.line((x,y,x+w,y),fill='#755f25',width=2);d.line((x,y+h,x+w,y+h),fill='#755f25',width=2)
  size=25 if n['id']=='title' else 15 if kind=='store' else 17 if kind in ['process','actor'] else 14
  f=ImageFont.truetype(boldpath if kind in ['process','actor','store'] or n['id']=='title' else fontpath,size)
  text=wrap(n['t'],f,w-24,d)
  box=d.multiline_textbbox((0,0),text,font=f,spacing=6,align='center');tw,th=box[2]-box[0],box[3]-box[1]
  d.multiline_text((x+(w-tw)/2,y+(h-th)/2),text,font=f,spacing=6,align='center',fill='#1e293b')
 for edge in page['edges']:
  x1,x2,y=edge['x1'],edge['x2'],edge['y']
  if edge['input']:
   start=x1 if x1==310 else x2;end=x2 if x1==310 else x1
  else:
   start=x2 if x1==310 else x1;end=x1 if x1==310 else x2
  d.line((start,y,end,y),fill='#334155',width=2);sgn=1 if end>start else -1
  d.polygon([(end,y),(end-sgn*12,y-5),(end-sgn*12,y+5)],fill='#334155')
  f=ImageFont.truetype(fontpath,13);tw=d.textlength(edge['t'],font=f)
  d.text(((x1+x2-tw)/2,y+(8 if edge['dir'] else -22)),edge['t'],font=f,fill='#334155')
 im.save('D:/wamp64/Brewlearn/docs/diagrams/BrewLearn-DFD-muc-0-page-'+str(index+1)+'.png')

